args.sparql:
SELECT DISTINCT ?birthPlace ?birthPlaceLabel WHERE {
  VALUES ?person { dbr:Nicki_Minaj }
  {
    ?person dbo:birthPlace ?birthPlace .
  }
  UNION
  {
    ?person dbp:birthPlace ?birthPlace .
  }
  UNION
  {
    ?person dbp:birth_place ?birthPlace .
  }
  UNION
  {
    ?person dbp:placeOfBirth ?birthPlace .
  }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER (lang(?birthPlaceLabel) = 'en') }
} LIMIT 10

